/* Wilder Horizons: continuous terrain, mastery, wandering relic traders and energy. */
'use strict';
const H8={solidWorld,terrainImpact,terrainChunk,stepMove,losClear,buildShallows,showTelegraph,shockwave,hazard,initializeLoadouts,computeStats,addXP,playerCarry,makeSave,restoreWorld,validSave,loadLevel,createVendor,vendorRecord,nearStation,showVendor,updateCrates,refreshTradeHeader,updateHUD,updateObjectives,createUI,tickSurvival,startSurvivalWave,adventureTick,moveWildCamp,fireProjectile,updateFX,showTitle,showControls};
// The rendered surface and rig origins differ by 25 cm, as in the dungeon.
function rawWildHeight(x,z){const seed=(WILD.seed||G.levelSeed)>>>0,p=(seed%10007)*.00063,q=((seed>>>8)%7993)*.00079;return .75+5.5*Math.sin(x*.019+p)*Math.cos(z*.018-q)+2.6*Math.sin(x*.037+z*.031+q)+.8*Math.cos(x*.075-q)*Math.sin(z*.067+p);}
function terrainVertex(x,z){const cx=Math.floor(x/32)*32+16,cz=Math.floor(z/32)*32+16,d=Math.hypot(x-cx,z-cz),h=rawWildHeight(x,z);if(d>=9)return h;const t=clamp((d-3)/6,0,1),blend=t*t*(3-2*t);return lerp(rawWildHeight(cx,cz)-.10,h,blend);}
function surfaceAt(x,z){if(G.mode!=='outdoors')return .75;const ix=Math.floor(x),iz=Math.floor(z),u=x-ix,v=z-iz,h00=terrainVertex(ix,iz),h10=terrainVertex(ix+1,iz),h01=terrainVertex(ix,iz+1),h11=terrainVertex(ix+1,iz+1);return u>=v?h00+u*(h10-h00)+v*(h11-h10):h00+v*(h01-h00)+u*(h11-h01);}
function groundAt(x,z){return G.mode==='outdoors'?surfaceAt(x,z)+.25:GROUND;}
function terrainFootTarget(e,target){if(G.mode!=='outdoors'||e.spec?.fly||e.dead||e.rollT>=0)return target;e.rig.root.computeWorldMatrix(true);const worldPoint=BABYLON.Vector3.TransformCoordinates(target,e.rig.root.getWorldMatrix());target.y+=(groundAt(worldPoint.x,worldPoint.z)-groundAt(e.pos.x,e.pos.z))/e.rig.root.scaling.y;return target;}
function terrainFootNormal(e,target,up=V3(0,1,0)){if(G.mode!=='outdoors'||e.spec?.fly||e.dead||e.rollT>=0)return up;const m=e.rig.root.getWorldMatrix(),w=BABYLON.Vector3.TransformCoordinates(target,m),n=V3(surfaceAt(w.x-.15,w.z)-surfaceAt(w.x+.15,w.z),.3,surfaceAt(w.x,w.z-.15)-surfaceAt(w.x,w.z+.15)).normalize(),local=BABYLON.Vector3.TransformNormal(n,BABYLON.Matrix.Invert(m)).normalize();return local.add(up.subtract(V3(0,1,0))).normalize();}
solidWorld=function(x,y,z){return G.mode==='outdoors'?(y<surfaceAt(x,z)-.005?1:0):H8.solidWorld(x,y,z);};
terrainChunk=function(cx,cz){if(G.mode!=='outdoors')return H8.terrainChunk(cx,cz);const pos=[],norm=[],col=[],idx=[],R=rngFor('ground:'+cx+','+cz);for(let x=0;x<32;x++)for(let z=0;z<32;z++){const wx=cx*32+x,wz=cz*32+z,b=outdoorBiome(wx,wz),path=Math.abs(Math.sin(wx*.031)+Math.cos(wz*.034))<.17,n=Math.sin(wx*.12)*Math.cos(wz*.13)+Math.sin(wx*.021+wz*.047),color=BABYLON.Color3.FromHexString(path?b.rock[3]:n>.3?b.moss[Math.floor(R()*3)]:b.rock[Math.floor(R()*3)]).scale(.88+R()*.15),i=pos.length/3;for(const [dx,dz]of[[0,0],[1,0],[1,1],[0,1]]){const X=wx+dx,Z=wz+dz,N=V3(terrainVertex(X-1,Z)-terrainVertex(X+1,Z),2,terrainVertex(X,Z-1)-terrainVertex(X,Z+1)).normalize();pos.push(X,terrainVertex(X,Z),Z);norm.push(N.x,N.y,N.z);col.push(color.r,color.g,color.b,1);}idx.push(i,i+2,i+1,i,i+3,i+2);}const mesh=new BABYLON.Mesh('biomeTerrain_'+cx+'_'+cz,scene),v=new BABYLON.VertexData();v.positions=new Float32Array(pos);v.normals=new Float32Array(norm);v.colors=new Float32Array(col);v.indices=idx;v.applyToMesh(mesh);mesh.material=matVox(scene);mesh.receiveShadows=true;mesh.isPickable=false;world.chunks.push(mesh);return mesh;};
// Split a swept segment at every grid edge and triangle diagonal. Each interval
// is linear, so shallow grazing impacts cannot tunnel through a hill crest.
terrainImpact=function(a,b){if(G.mode!=='outdoors')return H8.terrainImpact(a,b);const d=b.subtract(a),cuts=[0,1];for(const axis of['x','z']){if(Math.abs(d[axis])<1e-10)continue;const min=Math.min(a[axis],b[axis]),max=Math.max(a[axis],b[axis]);for(let k=Math.floor(min)+1;k<max;k++)cuts.push((k-a[axis])/d[axis]);}cuts.sort((x,y)=>x-y);const extra=[];for(let i=0;i<cuts.length-1;i++){const mid=(cuts[i]+cuts[i+1])*.5,ix=Math.floor(a.x+d.x*mid),iz=Math.floor(a.z+d.z*mid),den=d.x-d.z;if(Math.abs(den)>1e-10){const t=(ix-iz-a.x+a.z)/den;if(t>cuts[i]+1e-9&&t<cuts[i+1]-1e-9)extra.push(t);}}cuts.push(...extra);cuts.sort((x,y)=>x-y);const altitude=t=>a.y+d.y*t-surfaceAt(a.x+d.x*t,a.z+d.z*t);let previous=cuts[0],h=altitude(previous);if(h<=0)return 0;for(let i=1;i<cuts.length;i++){const t=cuts[i],next=altitude(t);if(next<=0)return previous+(t-previous)*h/(h-next);previous=t;h=next;}return null;};
stepMove=function(e,dx,dz){H8.stepMove(e,dx,dz);if(G.mode==='outdoors')e.pos.y=groundAt(e.pos.x,e.pos.z)+(e.spec?.fly?(e.floatY??e.spec.fly):0);};
losClear=function(a,b){if(G.mode!=='outdoors')return H8.losClear(a,b);const from=a.add(V3(0,1.05,0)),to=b.add(V3(0,1.05,0));if(terrainImpact(from,to)!==null)return false;const d=to.subtract(from),length=d.x*d.x+d.z*d.z;if(length<.0001)return true;for(const q of world.blockers){if(q.crate?.open||(q.height||0)<.8)continue;const t=((q.x-from.x)*d.x+(q.z-from.z)*d.z)/length;if(t<.03||t>.97)continue;if(Math.hypot(from.x+d.x*t-q.x,from.z+d.z*t-q.z)>=q.r*.85)continue;const y=from.y+d.y*t,base=groundAt(q.x,q.z);if(y>base-.25&&y<base+(q.height||2.6))return false;}return true;};
function drapeMesh(mesh,offset=.04){if(G.mode!=='outdoors'||!mesh?.getVerticesData)return;mesh.computeWorldMatrix(true);const data=mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);if(!data)return;const out=Array.from(data),mat=mesh.getWorldMatrix(),inv=BABYLON.Matrix.Invert(mat);for(let i=0;i<out.length;i+=3){const w=BABYLON.Vector3.TransformCoordinates(V3(out[i],out[i+1],out[i+2]),mat);w.y=surfaceAt(w.x,w.z)+offset;const p=BABYLON.Vector3.TransformCoordinates(w,inv);out[i+1]=p.y;}mesh.setVerticesData(BABYLON.VertexBuffer.PositionKind,out,true);mesh.refreshBoundingInfo();}
buildShallows=function(...args){H8.buildShallows(...args);if(G.mode==='outdoors'){const w=EXT.waters.at(-1);drapeMesh(w.mesh,.055);w.base=w.mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind).slice();}};
showTelegraph=function(e){const old=e.telegraph;H8.showTelegraph(e);if(!old&&e.telegraph)drapeMesh(e.telegraph,.045);};
hazard=function(...args){const p=args[0].clone();p.y=groundAt(p.x,p.z);args[0]=p;H8.hazard(...args);drapeMesh(WILD.hazards.at(-1)?.mesh,.06);};

const SKILLS={stride:{name:'Fleetfoot',stat:'Movement speed',step:3,max:12},tempo:{name:'Combat rhythm',stat:'Attack speed',step:3,max:15},force:{name:'Weapon mastery',stat:'Damage',step:4,max:30},vigor:{name:'Vitality',stat:'Maximum health',step:5,max:30},mending:{name:'Renewal',stat:'Health recovery speed',step:12,max:15},endurance:{name:'Second wind',stat:'Stamina recovery',step:8,max:15},reserve:{name:'Endurance',stat:'Maximum stamina',step:4,max:20},precision:{name:'Deadeye',stat:'Critical chance',step:1,max:15}};
function freshTraining(){return{version:1,bank:0,earned:0,spent:0,ranks:Object.fromEntries(Object.keys(SKILLS).map(k=>[k,0]))};}
function trainingRecord(){const t=player.training||freshTraining();return{...t,ranks:{...t.ranks}};}
function legacyTrainingXP(carry){let total=carry?.xp||0,next=120;for(let l=1;l<(carry?.level||1)&&l<150;l++){total+=next;next=Math.round(next*1.35);}return Math.min(1e12,Math.round(total));}
initializeLoadouts=function(carry,snapshot){const saved=snapshot?.player?.training||carry?.training;player.training=saved?{...saved,ranks:{...freshTraining().ranks,...saved.ranks}}:freshTraining();if(!saved&&carry){player.training.bank=player.training.earned=legacyTrainingXP(carry);}H8.initializeLoadouts(carry,snapshot);};
computeStats=function(p){const hp=p.hp,s=H8.computeStats(p),r=p.training?.ranks||{};p.speed*=1+(r.stride||0)*.03;s.ms+=(r.stride||0)*3;s.atkSpeed*=1+(r.tempo||0)*.03;s.baseDmg*=1+(r.force||0)*.04;p.maxhp*=1+(r.vigor||0)*.05;p.maxstam*=1+(r.reserve||0)*.04;s.stamr+=(r.endurance||0)*8;s.crit=Math.min(100,s.crit+(r.precision||0));s.regenMultiplier=1+(r.mending||0)*.12;p.hp=Math.min(hp,p.maxhp);return s;};
addXP=function(value){if(!Number.isFinite(value)||value<=0)return;player.training??=freshTraining();const credit=Math.round(value);player.training.bank+=credit;player.training.earned+=credit;H8.addXP(value);};
playerCarry=function(){return{...H8.playerCarry(),training:trainingRecord()};};
function skillCost(key,rank=player.training?.ranks[key]||0){return Math.round(120*Math.pow(rank+1,1.5));}
function buySkill(key){const s=SKILLS[key],t=player?.training;if(!s||!t||modalType!=='skills'||!G.running||player.dead)return false;const rank=t.ranks[key],cost=skillCost(key,rank);if(rank>=s.max||t.bank<cost)return false;t.bank-=cost;t.spent+=cost;t.ranks[key]++;computeStats(player);saveGame(true);sound('level');showSkills();$('skill_'+key).focus();return true;}
function showSkills(){if(!G.running||player.dead)return;if(G.invOpen)toggleInv(false);const t=player.training||freshTraining();showModal('Wayfarer mastery','<div class="masterySummary"><b>'+Math.floor(t.bank).toLocaleString()+' XP to spend</b><span>Level '+player.level+' · '+Math.floor(player.xp)+' / '+player.xpNext+' XP toward next level</span></div><p>All earned experience also funds training. Upgrades stay with your character and every build throughout this expedition. Training does not reduce your level progress.</p><div class="masteryGrid">'+Object.entries(SKILLS).map(([k,s])=>{const r=t.ranks[k],cost=skillCost(k),max=r>=s.max;return'<article class="masteryCard"><div><b>'+s.name+'</b><span>'+s.stat+'</span></div><strong>+'+(r*s.step)+'% <small>→ '+(max?'MASTERED':'+'+((r+1)*s.step)+'%')+'</small></strong><progress value="'+r+'" max="'+s.max+'" aria-label="'+s.stat+' rank"></progress><div><span>Rank '+r+' / '+s.max+'</span><button id="skill_'+k+'" '+(max||t.bank<cost?'disabled':'')+'>'+(max?'Mastered':cost.toLocaleString()+' XP · upgrade')+'</button></div></article>';}).join('')+'</div><p>Renewal speeds up recovery after five quiet seconds. Critical chance is capped at 100%. Press K or Escape to return.</p>','skills');for(const k of Object.keys(SKILLS))$('skill_'+k).onclick=()=>buySkill(k);}

const CARAVAN={camp:null,visit:null,lastVisitWave:0,constructing:false};
const TRAVELERS=[{name:'Aster, Starforged Broker',color:'#91c5ff'},{name:'Nyra, Keeper of Relics',color:'#dda5f1'},{name:'Rook, the Sunward Pilgrim',color:'#ffe0a3'}];
function collisionMerchants(){return [...new Set([CARAVAN.camp,CARAVAN.visit?.npc,vendor].filter(v=>v?.rig&&!v.rig.root.isDisposed()))];}
createVendor=function(){H8.createVendor();vendor.name='Sable, the Wayfarer';if(!CARAVAN.constructing)CARAVAN.camp=vendor;return vendor;};
function merchantRecord(npc){const previous=vendor;try{vendor=npc;return H8.vendorRecord();}finally{vendor=previous;}}
function nearestMerchant(){return collisionMerchants().filter(v=>!v.traveling||CARAVAN.visit?.phase==='trading').sort((a,b)=>BABYLON.Vector3.DistanceSquared(a.pos,player.pos)-BABYLON.Vector3.DistanceSquared(b.pos,player.pos))[0]||CARAVAN.camp;}
function selectMerchant(){if(TRADE.active)return;const closest=nearestMerchant();if(closest){vendor=closest;RUN.vendorPos=closest.pos.clone();}}
nearStation=function(which){if(which==='vendor'){if(!TRADE.active)selectMerchant();return vendor&&(!vendor.traveling||CARAVAN.visit?.phase==='trading')&&Math.hypot(vendor.pos.x-player.pos.x,vendor.pos.z-player.pos.z)<2.75;}return H8.nearStation(which);};
showVendor=function(){selectMerchant();return H8.showVendor();};
function caravanPoint(origin,min=4,max=7){for(let i=0;i<32;i++){const a=i*2.399+WILD.wave*.7,r=min+(max-min)*(i%5)/4,p=origin.add(V3(Math.sin(a)*r,0,Math.cos(a)*r));p.y=groundAt(p.x,p.z);if(clearPoint(p.x,p.z,1)&&!world.blockers.some(b=>Math.hypot(b.x-p.x,b.z-p.z)<b.r+1.5))return p;}const fallback=origin.add(V3(2,0,2));fallback.y=groundAt(fallback.x,fallback.z);return fallback;}
function caravanEntry(goal){for(let i=0;i<24;i++){const a=i*2.399+WILD.wave,p=goal.add(V3(Math.cos(a)*9,0,Math.sin(a)*9));let clear=true;for(let j=0;j<=20;j++){const t=j/20,x=lerp(goal.x,p.x,t),z=lerp(goal.z,p.z,t);if(world.blockers.some(b=>Math.hypot(b.x-x,b.z-z)<b.r+.7)){clear=false;break;}}if(clear){p.y=groundAt(p.x,p.z);return p;}}return goal.clone();}
function setVisitorPosition(visit,pos){const e=visit.npc;e.pos.copyFrom(pos);e.pos.y=groundAt(pos.x,pos.z);e.rig.root.position.copyFrom(e.pos);e.rig.root.rotation.y=e.yaw;for(const b of visit.blocks){b.x=e.pos.x+b.localX*Math.cos(e.yaw)+b.localZ*Math.sin(e.yaw);b.z=e.pos.z-b.localX*Math.sin(e.yaw)+b.localZ*Math.cos(e.yaw);}if(vendor===e)RUN.vendorPos=e.pos.clone();indexBlockers();COLLISIONS.dynamicTime=-1;}
function setVisitorTable(visit,visible){visit.table?.setEnabled(visible);world.blockers=world.blockers.filter(b=>!visit.blocks.includes(b));world.blockers.push(...(visible?visit.blocks:visit.blocks.slice(0,1)));indexBlockers();COLLISIONS.dynamicTime=-1;}
function createTraveler(saved=null){const profile=TRAVELERS[Math.floor((saved?.wave??WILD.wave)/3-1)%TRAVELERS.length],previous=vendor,oldRoom=startRoom,oldPos=RUN.vendorPos,goal=saved?V3(...saved.goal):caravanPoint(player.pos),entry=saved?V3(...saved.pos):caravanEntry(goal),before=world.blockers.length;CARAVAN.constructing=true;try{startRoom={x:goal.x/TILE-3,y:goal.z/TILE-3,w:6,h:6};H8.createVendor();const e=vendor;e.name=profile.name;e.traveling=true;e.radius=.45;e.speed=1.65;e.floatY=0;e.rig.moveBlend=0;const blocks=world.blockers.slice(before);for(const b of blocks){b.visitor=true;const dx=b.x-e.pos.x,dz=b.z-e.pos.z;b.localX=dx*Math.cos(e.yaw)-dz*Math.sin(e.yaw);b.localZ=dx*Math.sin(e.yaw)+dz*Math.cos(e.yaw);}const table=e.rig.root.getChildMeshes().find(m=>m.name.includes('merchantTable')),backpack=cachedArt(scene,'travelerPack|'+profile.color,()=>new DetailVox().box(-.19,.7,.12,.19,1.17,.30,'#453b53').box(-.15,.77,.31,.15,1.1,.34,'#77627e').box(-.21,.79,.12,-.17,1.20,.28,'#c7ad80').box(.17,.79,.12,.21,1.20,.28,'#c7ad80').ell(0,1.02,.36,.06,.09,.015,profile.color).build('relic courier pack',scene));attachProto(backpack,e.rig.root,e.rig.parts);
 const level=Math.min(99990,Math.ceil(Math.max(G.depth*4+35,player.level*4+25,...ownedEquipment().map(it=>it.ilvl*1.35+18))));e.stock=makePremiumStock({seed:contentHash('caravan:'+WILD.wave+':'+WILD.region,G.levelSeed),level,rarity:5,collections:2,markup:1.9});
 if(saved){e.stock=saved.merchant.stock.map(r=>({item:reviveItem(r.item),sold:r.sold,price:r.price}));e.collections=saved.merchant.collections.map(c=>({...c,ids:[...c.ids]}));e.potionsBought=saved.merchant.potionsBought||0;e.pastPurchases=saved.merchant.pastPurchases||0;}
 const visit={npc:e,blocks,table,goal,exit:saved?V3(...saved.exit):entry.clone(),phase:saved?.phase||'arriving',wave:saved?.wave||WILD.wave,elapsed:saved?.elapsed||0};CARAVAN.visit=visit;setVisitorPosition(visit,entry);setVisitorTable(visit,visit.phase==='trading');updateRig(e,0);return visit;
 }finally{CARAVAN.constructing=false;startRoom=oldRoom;vendor=previous;RUN.vendorPos=oldPos;}}
function dismissTraveler(){const v=CARAVAN.visit;if(!v)return;setVisitorTable(v,false);if(vendor===v.npc){vendor=CARAVAN.camp;RUN.vendorPos=vendor?.pos.clone();}world.blockers=world.blockers.filter(b=>!v.blocks.includes(b));indexBlockers();killNode(v.npc.rig.root);CARAVAN.visit=null;COLLISIONS.dynamicTime=-1;}
function tickCaravan(dt){const v=CARAVAN.visit;if(!v)return;v.elapsed+=dt;const e=v.npc;if(v.phase==='arriving'||v.phase==='departing'){const target=v.phase==='arriving'?v.goal:v.exit,d=target.subtract(e.pos);d.y=0;const distance=d.length();e.moveSpeedNow=distance>.08?1.65:0;if(distance>.08){d.normalize();e.yaw=dampAngle(e.yaw,yawTo(d),Math.min(1,dt*5));e.vel.copyFrom(d.scale(1.65));const p=e.pos.add(d.scale(Math.min(distance,dt*1.65)));setVisitorPosition(v,p);}if(distance<.12||v.elapsed>14){if(v.phase==='departing'){dismissTraveler();saveGame(true);return;}setVisitorPosition(v,v.goal);v.phase='trading';v.elapsed=0;e.moveSpeedNow=0;e.vel.setAll(0);setVisitorTable(v,true);toast(e.name+' has arrived · Mythic relics and complete sets',TRAVELERS[Math.floor(v.wave/3-1)%3].color);saveGame(true);}}else{e.moveSpeedNow=0;const d=player.pos.subtract(e.pos);e.headYaw=clamp(yawTo(d)-e.yaw,-.6,.6);}e.rig.root.rotation.y=e.yaw;if(e!==vendor)updateRig(e,dt);if(CARAVAN.camp&&vendor!==CARAVAN.camp)updateRig(CARAVAN.camp,dt);}
tickSurvival=function(dt){const phase=WILD.phase,wave=WILD.wave;H8.tickSurvival(dt);if(G.mode==='outdoors'&&['spawning','fighting'].includes(phase)&&['intermission','gate'].includes(WILD.phase)&&wave>0&&wave%3===0&&CARAVAN.lastVisitWave<wave){dismissTraveler();CARAVAN.lastVisitWave=wave;createTraveler();if(WILD.phase==='intermission')WILD.timer=100;toast('A relic traveler is approaching · extended respite','#d8b9f1');saveGame(true);}};
startSurvivalWave=function(){if(CARAVAN.visit){CARAVAN.visit.phase='departing';CARAVAN.visit.elapsed=0;setVisitorTable(CARAVAN.visit,false);}H8.startSurvivalWave();};
adventureTick=function(dt){H8.adventureTick(dt);if(G.mode==='outdoors')tickCaravan(dt);};
moveWildCamp=function(pos){dismissTraveler();vendor=CARAVAN.camp||vendor;H8.moveWildCamp(pos);};
updateCrates=function(dt){selectMerchant();H8.updateCrates(dt);if(nearStation('vendor')&&!G.shaft){$('prompt').style.display='block';$('prompt').innerHTML='<b>E / USE</b> Trade with '+escaped(vendor.name);}};
refreshTradeHeader=function(){H8.refreshTradeHeader();if(TRADE.active){$('merchantName').textContent=vendor.name||'Sable, the Wayfarer';$('tradeStock').textContent=vendor.traveling?'Mythic relics':'Sable’s stock';if(TRADE.side==='vendor')$('bagTitle').textContent=vendor.traveling?'The traveler’s relics':'Sable’s stock';}};

// Soft, compact energy cores with short additive particle wakes.
const ENERGY={scene:null,texture:null,materials:new Map(),proto:null};
function energyMaterial(color){if(ENERGY.scene!==scene){ENERGY.scene=scene;ENERGY.materials.clear();ENERGY.proto=null;const tex=new BABYLON.DynamicTexture('energy falloff',64,scene,false),ctx=tex.getContext(),g=ctx.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.18,'rgba(255,255,255,.9)');g.addColorStop(.5,'rgba(255,255,255,.22)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,64,64);tex.hasAlpha=true;tex.update();ENERGY.texture=tex;}
 if(!ENERGY.materials.has(color)){const m=new BABYLON.StandardMaterial('energy '+color,scene);m.diffuseTexture=ENERGY.texture;m.opacityTexture=ENERGY.texture;m.emissiveColor=BABYLON.Color3.FromHexString(color);m.disableLighting=true;m.backFaceCulling=false;m.alphaMode=BABYLON.Engine.ALPHA_ADD;m.disableDepthWrite=true;ENERGY.materials.set(color,m);}return ENERGY.materials.get(color);}
function energySprite(color,size){const material=energyMaterial(color);if(!ENERGY.proto){ENERGY.proto=BABYLON.MeshBuilder.CreatePlane('energy sprite prototype',{size:1},scene);ENERGY.proto.isVisible=false;}const m=ENERGY.proto.clone('energy wisp');m.isVisible=true;m.material=material;m.isPickable=false;m.billboardMode=BABYLON.Mesh.BILLBOARDMODE_ALL;m.scaling.setAll(size);return m;}
fireProjectile=function(from,dir,opts){const mesh=new BABYLON.Mesh('energy bolt',scene);mesh.position.copyFrom(from);const glow=energySprite(opts.color||'#ff8a3d',opts.fromPlayer?.21:.25);glow.parent=mesh;const core=energySprite('#f1fcff',.065);core.parent=mesh;core.position.copyFrom(dir.scale(.02));G.projectiles.push({mesh,vel:dir.scale(opts.speed||20),dmg:opts.dmg,life:opts.life||3.5,fromPlayer:!!opts.fromPlayer,color:opts.color||'#ff8a3d',element:opts.element,trail:0});};
function emitEnergyTrail(p,from,to,dt){const distance=BABYLON.Vector3.Distance(from,to),count=Math.min(SETTINGS.quality==='low'?3:5,Math.max(1,Math.ceil(distance/.15)));for(let i=0;i<count&&G.fx.length<210;i++){const size=.035+Math.random()*.05,m=energySprite(p.color,size);m.position.copyFrom(BABYLON.Vector3.Lerp(from,to,(i+.5)/count));m.position.addInPlace(V3((Math.random()-.5)*.035,(Math.random()-.5)*.035,(Math.random()-.5)*.035));const life=.16+Math.random()*.11;G.fx.push({mesh:m,vel:p.vel.scale(-.022).add(V3(0,.04,0)),life,max:life,grav:0,energy:true,size});}}
updateFX=function(dt){H8.updateFX(dt);for(const f of G.fx)if(f.ring&&G.mode==='outdoors')drapeMesh(f.mesh,.06);for(const f of G.fx)if(f.energy){const t=Math.max(0,f.life/f.max);f.mesh.visibility=t;f.mesh.scaling.setAll(f.size*(.35+.65*t));}};

function caravanRecord(){const v=CARAVAN.visit;return{version:1,lastVisitWave:CARAVAN.lastVisitWave,visit:v?{wave:v.wave,phase:v.phase,elapsed:v.elapsed,pos:v.npc.pos.asArray(),goal:v.goal.asArray(),exit:v.exit.asArray(),merchant:merchantRecord(v.npc)}:null};}
makeSave=function(){const selectedMerchant=vendor;let d;try{vendor=CARAVAN.camp||vendor;d=H8.makeSave();}finally{vendor=selectedMerchant;}d.build='8 · Wilder Horizons';if(G.mode==='outdoors'){d.terrainRevision=1;d.caravan=caravanRecord();}return d;};
loadLevel=async function(...args){if(loadingLevel)return;CARAVAN.camp=null;CARAVAN.visit=null;CARAVAN.lastVisitWave=args[3]?.caravan?.lastVisitWave??Math.floor((args[3]?.wild?.wave||0)/3)*3;return H8.loadLevel(...args);};
restoreWorld=function(d){H8.restoreWorld(d);CARAVAN.camp=vendor;if(G.mode==='outdoors'){CARAVAN.lastVisitWave=d.caravan?.lastVisitWave??Math.floor(WILD.wave/3)*3;if(d.caravan?.visit)createTraveler(d.caravan.visit);for(const h of WILD.hazards){h.pos.y=groundAt(h.pos.x,h.pos.z);}}selectMerchant();markCollisionDirty();};
validSave=function(d){if(!H8.validSave(d))return false;const t=d.player.training;if(t){if(t.version!==1||![t.bank,t.earned,t.spent].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=1e12)||t.bank+t.spent!==t.earned||!t.ranks)return false;let spent=attackTrainingSpent(t);if(!Number.isFinite(spent))return false;for(const [k,s]of Object.entries(SKILLS)){const rank=t.ranks[k];if(!Number.isInteger(rank)||rank<0||rank>s.max)return false;for(let i=0;i<rank;i++)spent+=Math.round(120*Math.pow(i+1,1.5));}if(spent!==t.spent)return false;}const c=d.caravan;if(!c)return true;if(c.version!==1||!Number.isSafeInteger(c.lastVisitWave)||c.lastVisitWave<0||c.lastVisitWave>(d.wild?.wave||0))return false;const v=c.visit;if(!v)return true;const pos=p=>Array.isArray(p)&&p.length===3&&p.every(n=>Number.isFinite(n)&&Math.abs(n)<1e9);if(!Number.isSafeInteger(v.wave)||v.wave<3||v.wave!==c.lastVisitWave||v.wave%3||!['arriving','trading','departing'].includes(v.phase)||!Number.isFinite(v.elapsed)||v.elapsed<0||![v.pos,v.goal,v.exit].every(pos)||!v.merchant||v.merchant.stockRevision!==2||!Array.isArray(v.merchant.collections))return false;return H8.validSave({...d,vendor:v.merchant});};
updateHUD=function(){H8.updateHUD();if(player){$('skillsButton').textContent='Skills · '+Math.floor(player.training?.bank||0).toLocaleString()+' XP';$('skillsButton').title='Spend experience on character upgrades · K';const rect=$('vitals').getBoundingClientRect();if(rect.height>0&&Number.isFinite(rect.bottom)){const top=rect.bottom+14;$('objectives').style.top=top+'px';if(window.innerHeight)$('objectives').style.maxHeight=Math.max(70,window.innerHeight-top-185)+'px';}}};
updateObjectives=function(){H8.updateObjectives();const el=$('caravanNotice'),v=CARAVAN.visit;el.hidden=G.mode!=='outdoors'||!v;if(el.hidden)return;const distance=Math.round(BABYLON.Vector3.Distance(v.npc.pos,player.pos));$('caravanText').textContent=v.npc.name+' · '+(v.phase==='trading'?'trading':v.phase==='arriving'?'approaching':'leaving')+' · '+distance+' m';$('caravanReady').hidden=WILD.phase!=='intermission';$('caravanReady').disabled=v.phase!=='trading';$('caravanReady').textContent='Next wave · N · '+Math.ceil(Math.max(0,WILD.timer))+'s';};
createUI=function(){H8.createUI();$('vitals').insertAdjacentHTML('beforeend','<button id="skillsButton" aria-label="Character skills">Skills · 0 XP</button>');$('skillsButton').onclick=showSkills;$('questRows').insertAdjacentHTML('afterend','<div id="caravanNotice" hidden><span id="caravanText"></span><button id="caravanReady">Begin next wave</button></div>');$('caravanReady').onclick=readyForNextWave;};
showControls=function(){H8.showControls();$('modalBody').insertAdjacentHTML('beforeend','<p><b>K · Skills:</b> spend earned XP on movement, attacks, health and recovery. In survival, relic travelers arrive after every third cleared wave. Their visits extend the break; press N or choose Begin next wave when ready.</p>');};
showTitle=function(){H8.showTitle();$('buildMarker').textContent='WILDER HORIZONS · MASTERY & CARAVANS';};

function readyForNextWave(){if(!canAct()||G.mode!=='outdoors'||WILD.phase!=='intermission'||CARAVAN.visit?.phase!=='trading')return false;WILD.timer=0;return true;}
